using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 9.99m);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 9.99m);
        _cart.AddItem("SKU-002", 3, 4.50m);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 9.99m);
        _cart.AddItem("SKU-001", 2, 9.99m);
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 9.99m);
        _cart.RemoveItem("SKU-001");
    }

    [TestMethod]
    public void RemoveItem_AfterRemoval_ItemNotInTotal()
    {
        _cart.AddItem("SKU-001", 2, 5.00m);
        _cart.AddItem("SKU-002", 1, 3.00m);
        _cart.RemoveItem("SKU-001");

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(3.00m, total);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_DoesNotThrow()
    {
        _cart.RemoveItem("SKU-MISSING");
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsPriceTimesQuantity()
    {
        _cart.AddItem("SKU-001", 3, 10.00m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("SKU-001", 2, 5.00m);
        _cart.AddItem("SKU-002", 1, 12.50m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(22.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsRemainingItems()
    {
        _cart.AddItem("SKU-001", 1, 20.00m);
        _cart.AddItem("SKU-002", 1, 15.00m);
        _cart.RemoveItem("SKU-002");

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(20.00m, total);
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    public void ApplyCoupon_ValidCode_DoesNotThrow()
    {
        _cart.AddItem("SKU-001", 1, 50.00m);
        _cart.ApplyCoupon("SAVE10");
    }

    [TestMethod]
    public void ApplyCoupon_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        decimal totalBefore = _cart.CalculateTotal();

        _cart.ApplyCoupon("SAVE10");
        decimal totalAfter = _cart.CalculateTotal();

        Assert.IsTrue(totalAfter < totalBefore,
            $"Expected total after coupon ({totalAfter}) to be less than before ({totalBefore}).");
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_DoesNotThrow()
    {
        _cart.ApplyCoupon("SAVE10");
    }

    // --- Edge Cases ---

    [TestMethod]
    public void AddItem_ZeroQuantity_DoesNotAffectTotal()
    {
        _cart.AddItem("SKU-001", 0, 10.00m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void AddItem_ZeroPrice_DoesNotAffectTotal()
    {
        _cart.AddItem("SKU-FREE", 5, 0.00m);

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void RemoveItem_AllItems_TotalIsZero()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 2, 5.00m);
        _cart.RemoveItem("SKU-001");
        _cart.RemoveItem("SKU-002");

        decimal total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }
}

